const PIN_SECRETO = 'NetCore2026*';
const trigger = $('Telegram Trigger').item.json;
const chatId = String(trigger.message.chat.id);
const text = (trigger.message.text || '').trim();
const name = trigger.message.from.first_name || 'Usuario';
const lowerText = text.toLowerCase();

// Motor local primario (.128 / host.docker.internal) con fallback a .176
let ENGINE_BASE = 'http://host.docker.internal:11440';
try {
  await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://host.docker.internal:11440/subscribers',
    json: true,
    timeout: 800
  });
  ENGINE_BASE = 'http://host.docker.internal:11440';
} catch (_eLocal) {
  try {
    await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://192.168.1.50:11440/subscribers',
      json: true,
      timeout: 800
    });
    ENGINE_BASE = 'http://192.168.1.50:11440';
  } catch (_e176) {
    ENGINE_BASE = 'http://host.docker.internal:11440';
  }
}

let subs = [];
try {
  const subsRes = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://host.docker.internal:11440/subscribers',
    json: true,
    timeout: 5000
  });
  subs = Array.isArray(subsRes) ? subsRes : [];
} catch (e) {
  subs = [{ chat_id: '1558973693', name: 'Admin' }];
}

const isAuthorized = subs.some(s => String(s.chat_id) === chatId);

// 1. Mensaje de bienvenida /start
if (lowerText === '/start') {
  if (isAuthorized) {
    return [{ json: { action: 'reply', chatId, replyText: `👋 ¡Hola <b>${name}</b>! Ya estás autorizado en el NetCore NOC.

¿En qué puedo ayudarte hoy?
• <i>"Dime las alertas activas"</i> o <i>"/alertas"</i>
• <i>"Haz ping a 192.168.1.35"</i>
• <i>"Tráfico Nodo Este"</i> o <i>"/trafico [equipo]"</i>
• <i>"Estado del router principal"</i>
• <i>"/interfaces [equipo]"</i> (listar interfaces y Mbps)
• <i>"/reporte [equipo] [interfaz] [periodo]"</i> (reporte ejecutivo PDF enfocado)
• <i>"/dashboard"</i> (foto general NOC)
• <i>"/pdm"</i> (estado global PDM y backups PBS)
• <i>"/fotodatacenter"</i> (infografía visual en vivo PDM/PVE/PBS)` } }];
  } else {
    return [{ json: { action: 'reply', chatId, replyText: `🔒 <b>Acceso Restringido - NetCore NOC</b>

Por favor, ingresa el <b>PIN de autorización</b> para registrar tu cuenta y recibir alertas:` } }];
  }
}

// 2. Validación con PIN
if (text === PIN_SECRETO) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:11440/subscribers',
      body: { chat_id: chatId, name },
      json: true
    });
  } catch (e) {}
  return [{ json: { action: 'reply', chatId, replyText: `✅ <b>¡PIN Correcto!</b>

Tu usuario <b>${name}</b> ha sido autorizado con éxito y registrado para recibir alertas automáticas del NOC.

Comandos disponibles:
• <i>"/alertas"</i> (ver alertas y problemas activos)
• <i>"/interfaces [equipo]"</i> (ver puertos y Mbps)
• <i>"/trafico [equipo] [interfaz] [periodo]"</i>
• <i>"/reporte [equipo] [interfaz] [periodo]"</i> (PDF ejecutivo con gráfica)
• <i>"/dashboard"</i> (gráfico general)` } }];
}

// 3. No autorizado
if (!isAuthorized) {
  return [{ json: { action: 'reply', chatId, replyText: `⛔ <b>Acceso no autorizado</b>

No tienes permiso para interactuar con este bot. Ingresa el <b>PIN de acceso</b> corporativo para autorizar tu cuenta.` } }];
}

// 3b. Comando / Consulta de Alertas Activas (/alertas, /problemas, "¿hay problemas o caídas en la red?", etc.)
const isAlertsCmd = (
  lowerText === '/alertas' || lowerText === '/problemas' ||
  lowerText === 'alertas' || lowerText === 'problemas' ||
  lowerText.includes('alertas activas') || lowerText.includes('problemas activos') ||
  lowerText.includes('hay alertas') || lowerText.includes('hay problemas') ||
  lowerText.includes('hay caidas') || lowerText.includes('hay caídas') ||
  lowerText.includes('hay caidos') || lowerText.includes('hay caídos') ||
  lowerText.includes('algo caido') || lowerText.includes('algo caído') ||
  lowerText.includes('alguna caida') || lowerText.includes('alguna caída') ||
  lowerText.includes('problemas en la red') || lowerText.includes('problema en la red') ||
  lowerText.includes('caidas en la red') || lowerText.includes('caídas en la red') ||
  lowerText.includes('caidos en la red') || lowerText.includes('caídos en la red') ||
  lowerText.includes('estado de la red') || lowerText.includes('estatus de la red') ||
  lowerText.includes('como esta la red') || lowerText.includes('cómo está la red') ||
  lowerText.includes('que alertas hay') || lowerText.includes('qué alertas hay') ||
  lowerText.includes('que problemas hay') || lowerText.includes('qué problemas hay') ||
  lowerText.includes('dime las alertas') || lowerText.includes('ver alertas') || lowerText.includes('ver problemas') ||
  (/\b(alertas?|problemas?|ca[ií]das?|ca[ií]dos?)\b/i.test(lowerText) && (lowerText.includes('hay') || lowerText.includes('red') || lowerText.includes('dime') || lowerText.includes('ver') || lowerText.includes('actual') || lowerText.includes('ultim') || lowerText.includes('como') || lowerText.includes('cómo')))
) && !lowerText.includes('vm ') && !lowerText.includes('vm_') && !/\bvm\s*\d+\b/i.test(lowerText);

if (isAlertsCmd) {
  try {
    const probsData = await this.helpers.httpRequest({
      method: 'GET',
      url: `${ENGINE_BASE}/zabbix/problems?limit=12`,
      json: true,
      timeout: 12000
    });
    const recList = probsData.alertas_recientes_ultimos_6_min || [];
    const actList = probsData.problemas_activos_zabbix || [];
    let out = `🚨 <b>Alertas Recientes (Últimos 6 min)</b>\n\n`;
    if (recList.length > 0) {
      for (const a of recList.slice(0, 6)) {
        out += `🔴 <b>${a.equipo || 'Equipo'}</b>\n` +
               `• <b>Problema:</b> ${a.problema || 'N/D'}\n` +
               `• <b>Severidad:</b> ${a.severidad || 'Alta'}\n` +
               `• <b>Hora:</b> ${a.hora_evento || 'Reciente'}\n` +
               `• <b>Origen:</b> <code>${a.origen || 'Zabbix'}</code>\n\n`;
      }
    } else {
      out += `✅ No se han registrado alertas nuevas en los últimos 6 minutos.\n\n`;
    }

    out += `⚠️ <b>Problemas Activos en Zabbix (3 Servidores Unificados)</b>\n\n`;
    if (actList.length > 0) {
      for (const p of actList.slice(0, 10)) {
        const sev = String(p.severidad || 'Media');
        const emo = (sev === 'Desastre' || sev === 'Alta') ? '🔴' : (sev === 'Media' ? '🟠' : '🟡');
        out += `${emo} <b>${p.equipo || 'Host'}</b>\n` +
               `• <b>Problema:</b> ${p.problema || 'N/D'}\n` +
               `• <b>Severidad:</b> ${sev}\n` +
               `• <b>Hora:</b> ${p.hora || 'N/D'}\n` +
               `• <b>Origen:</b> <code>${p.origen || 'Zabbix'}</code>\n\n`;
      }
    } else {
      out += `🟢 Sin problemas activos reportados actualmente.`;
    }
    return [{ json: { action: 'reply', chatId, replyText: out.trim() } }];
  } catch (err) {
    return [{ json: { action: 'reply', chatId, replyText: `❌ Error al consultar alertas activas: ${err.message}` } }];
  }
}

// 4. Interfaces y Paginación (/interfaces, "interfaces de ...", "damelo paginado", "página 2", "siguiente")
const isPaginationOrIfaces = lowerText.startsWith('/interfaces') || lowerText.startsWith('/interfaz') || lowerText.startsWith('/puertos') ||
  lowerText.includes('interfaces') || lowerText.includes('puertos de') ||
  lowerText.includes('paginado') || lowerText.includes('paginada') ||
  lowerText.includes('pagina') || lowerText.includes('página') ||
  lowerText === 'siguiente' || lowerText === 'anterior' || lowerText.includes('mas interfaces') || lowerText.includes('más interfaces');

const isTrafficWord = lowerText.includes('trafico') || lowerText.includes('tráfico') || lowerText.includes('trarico') || lowerText.includes('tarfico') || lowerText.includes('consumo');

if (isPaginationOrIfaces && !isTrafficWord && !lowerText.includes('reporte') && !lowerText.includes('pdf')) {
  try {
    const ifacesRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${ENGINE_BASE}/interfaces-formatted?q=${encodeURIComponent(text)}&chat_id=${encodeURIComponent(chatId)}`,
      json: true,
      timeout: 12000
    });
    if (ifacesRes && ifacesRes.ok && ifacesRes.text) {
      return [{ json: { action: 'reply', chatId, replyText: ifacesRes.text } }];
    }
  } catch (err) {
    // Si falla el endpoint formateado, continúa abajo
  }
}

// 5b. Comando Grafico / Foto Datacenter PDM (PNG)
const isPdmChartCmd = lowerText === '/fotodatacenter' || lowerText === '/fotopdm' || lowerText === '/pdm-chart' || lowerText === '/pdm_chart' || lowerText === '/pdm-foto' || lowerText === '/pdm_foto' || lowerText === '/datacenter-chart' || lowerText === '/recursos' ||
  lowerText.includes('foto del datacenter') || lowerText.includes('foto de proxmox') || lowerText.includes('foto de pdm') || lowerText.includes('foto del cluster') ||
  lowerText.includes('foto de como esta') || lowerText.includes('foto de cómo está') || lowerText.includes('como esta en foto') || lowerText.includes('cómo está en foto') ||
  lowerText.includes('grafica del datacenter') || lowerText.includes('grafica de proxmox') || lowerText.includes('grafico del datacenter') || lowerText.includes('grafico de proxmox') ||
  lowerText.includes('captura de proxmox') || lowerText.includes('captura del datacenter') || lowerText.includes('captura de pdm') ||
  ((lowerText.includes('foto') || lowerText.includes('imagen') || lowerText.includes('grafic')) && (lowerText.includes('datacenter') || lowerText.includes('proxmox') || lowerText.includes('pdm') || lowerText.includes('cluster')));

if (isPdmChartCmd) {
  return [{
    json: {
      action: 'image',
      imageUrl: `${ENGINE_BASE}/generate-pdm-chart`,
      chatId,
      caption: `📊 <b>Proxmox Datacenter Manager (PDM) — Snapshot Visual</b>\n\n` +
               `🖥️ <b>PVE Clúster:</b> CPU, Memoria RAM y Almacenamiento consumido.\n` +
               `💾 <b>PBS Respaldos:</b> Estado del nodo y espacio de backups.\n` +
               `📈 <b>Top VMs:</b> Máquinas virtuales con mayor consumo de CPU.`
    }
  }];
}

// 5. Comando Dashboard Visual (PNG)
if (lowerText === '/dashboard' || lowerText === '/graficas' || lowerText.includes('dashboard') || lowerText.includes('graficas del dashboard') || lowerText.includes('grafica del dashboard')) {
  return [{
    json: {
      action: 'image',
      imageUrl: `${ENGINE_BASE}/generate-dashboard-chart`,
      chatId,
      caption: `📊 <b>Dashboard Ejecutivo NetCore NOC en Tiempo Real</b>\nDisponibilidad de hosts, distribución de severidades y tráfico en troncales.`
    }
  }];
}

// 6. Consulta de Tráfico (Comando /trafico o lenguaje natural: "trafico de nodo este", "trarico de nodo este", "dame el trafico saliendo...")
const isTrafficQuery = lowerText.startsWith('/trafico') || lowerText.startsWith('/grafico') || lowerText.startsWith('/grafica') ||
  lowerText.includes('trafico') || lowerText.includes('tráfico') || lowerText.includes('trarico') || lowerText.includes('tarfico') ||
  lowerText.includes('consumo de') || lowerText.includes('velocidad de') || lowerText.includes('ancho de banda');

const isReportCmd = lowerText.startsWith('/reporte') || lowerText.startsWith('/pdf') || lowerText.includes('reporte pdf') || lowerText.includes('reporte de');

if (isTrafficQuery && !isReportCmd) {
  try {
    const summaryRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${ENGINE_BASE}/traffic-summary?q=${encodeURIComponent(text)}&chat_id=${encodeURIComponent(chatId)}`,
      json: true,
      timeout: 12000
    });

    if (summaryRes && summaryRes.ok) {
      const qParams = [
        `target=${encodeURIComponent(summaryRes.host)}`,
        `period=${encodeURIComponent(summaryRes.period || '24h')}`
      ];
      if (summaryRes.interface) {
        qParams.push(`interface=${encodeURIComponent(summaryRes.interface)}`);
      }
      return [{
        json: {
          action: 'image',
          imageUrl: `${ENGINE_BASE}/generate-traffic-chart?${qParams.join('&')}`,
          chatId,
          caption: summaryRes.caption
        }
      }];
    }
  } catch (err) {
    // Si falla summary, continúa con el handler legacy
  }

  // Fallback a parser tradicional si summary no resolvió
  const parts = text.split(/\s+/);
  const periodRegex = /^(today|hoy|now\/d|\d+\s*(m|min|mins|minuto|minutos|h|hr|hrs|hora|horas|d|dia|dias|w|sem|semanas|mo|mes|meses|y|anio|ano|anios|anos)|\d+)$/i;

  let target = '';
  let iface = '';
  let period = '24h';

  if (parts.length === 2) {
    target = parts[1];
  } else if (parts.length === 3) {
    if (periodRegex.test(parts[2])) {
      target = parts[1];
      period = parts[2];
    } else {
      target = parts[1];
      iface = parts[2];
    }
  } else if (parts.length >= 4) {
    target = parts[1];
    iface = parts[2];
    period = parts[3];
  }

  const queryParams = [`period=${encodeURIComponent(period)}`];
  if (target) queryParams.push(`target=${encodeURIComponent(target)}`);
  if (iface) queryParams.push(`interface=${encodeURIComponent(iface)}`);

  return [{
    json: {
      action: 'image',
      imageUrl: `${ENGINE_BASE}/generate-traffic-chart?${queryParams.join('&')}`,
      chatId,
      caption: `📈 <b>Gráfico de Tráfico en Tiempo Real</b>
Objetivo: <b>${iface || target || 'Red'}</b> ${iface ? `(${target})` : ''}
Periodo: <b>${period}</b>

Monitoreo de red de alta precisión generado desde Zabbix.`
    }
  }];
}

// 7. Comando de Reporte PDF (/reporte [interfaz o host] [periodo] o /reporte [host] [interfaz] [periodo])
if (isReportCmd) {
  const periodRegex = /^(today|hoy|now\/d|\d+\s*(m|min|mins|minuto|minutos|h|hr|hrs|hora|horas|d|dia|dias|w|sem|semanas|mo|mes|meses|y|anio|ano|anios|anos)|\d+)$/i;

  let period = '24h';
  let host = '';
  let iface = '';

  const isWeekly = lowerText.includes('semanal') || lowerText.includes('7 dias') || lowerText.includes('7 das') || lowerText.includes('7d');
  if (isWeekly) period = '7d';

  const isToday = lowerText.includes('today') || lowerText.includes('hoy');
  if (isToday) period = 'today';

  const parts = text.split(/\s+/);
  if (parts[0].toLowerCase() === '/reporte' || parts[0].toLowerCase() === '/pdf') {
    if (parts.length === 2) {
      host = parts[1];
    } else if (parts.length === 3) {
      if (periodRegex.test(parts[2])) {
        host = parts[1];
        period = parts[2];
      } else {
        host = parts[1];
        iface = parts[2];
      }
    } else if (parts.length >= 4) {
      host = parts[1];
      iface = parts[2];
      period = parts[3];
    }
  }

  return [{
    json: {
      action: 'report',
      reportUrl: `${ENGINE_BASE}/generate-report?period=${encodeURIComponent(period || '24h')}&host=${encodeURIComponent(host || '')}&interface=${encodeURIComponent(iface || '')}`,
      chatId,
      period,
      host,
      interface: iface,
      caption: `📄 <b>Reporte de Rendimiento y Tráfico</b>
${host ? `Objetivo: <b>${host}</b>` : ''}${iface ? ` | Interfaz: <b>${iface}</b>` : ''}
Periodo: <b>${period}</b>

Documento ejecutivo oficial generado en tiempo real.`
    }
  }];
}

// 7b. Comando PDM / Datacenter / Backups (/pdm, /datacenter, /backups, /pbs)
if (lowerText === '/pdm' || lowerText === '/datacenter' || lowerText === '/backups' || lowerText === '/pbs') {
  try {
    const pdmRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${ENGINE_BASE}/pdm/status`,
      json: true,
      timeout: 15000
    });
    const pve = pdmRes.pve_cluster;
    const pbs = pdmRes.pbs_backup;
    const jobs = pdmRes.ultimos_trabajos || [];
    let jobsTxt = '';
    for (const j of jobs.slice(0, 3)) {
      jobsTxt += `\n   • <code>${j.tipo || 'tarea'}</code> ${j.objetivo || 'clúster'}: <b>${j.estado || 'OK'}</b> (${j.hora_fin || 'N/D'})`;
    }
    const msg = `🏢 <b>Proxmox Datacenter Manager (PDM) — Estado Global</b>\n\n` +
      `🖥️ <b>Clúster PVE:</b>\n` +
      `• <b>Clústeres:</b> 🟢 2 activos (Cluster-Primary (DC-Alpha) + Cluster-Secondary (DC-Beta))\n` +
      `• <b>Nodos:</b> 🟢 ${pve.nodos_online} en línea (Node-01, Node-02, Node-03, Node-04, Node-05, Node-06)\n` +
      `• <b>Máquinas Virtuales:</b> 🟢 ${pve.vms_running} running | ⚪ ${pve.vms_stopped} stopped (Total: <b>${pve.vms_total}</b>)\n` +
      `• <b>Contenedores LXC:</b> 🟢 ${pve.lxc_running} running | ⚪ ${pve.lxc_stopped} stopped (Total: <b>${pve.lxc_total}</b>)\n\n` +
      `💾 <b>Servidor de Respaldo (PBS):</b>\n` +
      `• <b>Nodo:</b> 🟢 ${pbs.nodo_pbs} (${pbs.estado})\n` +
      `• <b>Datastores:</b> ${pbs.datastores_online} Online\n` +
      `• <b>Almacenamiento:</b> ${pbs.almacenamiento}\n` +
      `• <b>Respaldos:</b> ✅ ${pbs.respaldos_exitosos} exitosos | ❌ ${pbs.respaldos_fallidos} fallidos\n` +
      `• <b>Limpiezas (Prune):</b> ${pbs.prunes_completados} completados\n` +
      `• <b>Últimos trabajos:</b>${jobsTxt}`;
    return [{ json: { action: 'reply', chatId, replyText: msg } }];
  } catch (err) {
    return [{ json: { action: 'reply', chatId, replyText: `❌ Error al consultar PDM: ${err.message}` } }];
  }
}

// 7c. Consulta de Estado de Router / Switch / OLT / Equipo de Red
const isNetworkStatusQuery = (
  lowerText.includes('estado del router') || lowerText.includes('estado de') ||
  lowerText.includes('estatus del router') || lowerText.includes('estatus de') ||
  lowerText.includes('status del router') || lowerText.includes('status de') ||
  lowerText.includes('salud del router') || lowerText.includes('salud de') ||
  lowerText.includes('como esta el router') || lowerText.includes('cómo está el router') ||
  lowerText.includes('como esta') || lowerText.includes('cómo está')
) && !lowerText.includes('vm') && !lowerText.includes('proxmox') && !lowerText.includes('pdm') && !lowerText.includes('cluster') && !lowerText.includes('nodo');

if (isNetworkStatusQuery) {
  try {
    const stRes = await this.helpers.httpRequest({
      method: 'GET',
      url: `${ENGINE_BASE}/device-status-formatted?q=${encodeURIComponent(text)}&chat_id=${encodeURIComponent(chatId)}`,
      json: true,
      timeout: 10000
    });
    if (stRes && stRes.ok && stRes.text) {
      return [{ json: { action: 'reply', chatId, replyText: stRes.text } }];
    }
  } catch (err) {
    // Si falla o no se reconoce, pasa a la IA
  }
}


// 7d. Consulta de Estado de VM / Contenedor Proxmox (Fast path de alta velocidad)
const isVmStatusQuery = (
  lowerText.includes('estado de la vm') || lowerText.includes('estado del contenedor') ||
  lowerText.includes('estatus de la vm') || lowerText.includes('estatus del contenedor') ||
  lowerText.includes('status de la vm') || lowerText.includes('status del contenedor') ||
  lowerText.includes('estado de vm') || lowerText.includes('estatus de vm') ||
  lowerText.includes('info de la vm') || lowerText.includes('informacion de la vm') ||
  (lowerText.startsWith('/vm') && !lowerText.includes('start') && !lowerText.includes('reboot') && !lowerText.includes('stop') && !lowerText.includes('apagar') && !lowerText.includes('reiniciar')) ||
  (/\bvm\s*\d+\b/i.test(lowerText) && (lowerText.includes('estado') || lowerText.includes('estatus') || lowerText.includes('como esta') || lowerText.includes('cómo está') || lowerText.includes('status') || lowerText.includes('dime')))
) && !lowerText.includes('reboot') && !lowerText.includes('reiniciar') && !lowerText.includes('apagar') && !lowerText.includes('shutdown') && !lowerText.includes('stop') && !lowerText.includes('encender') && !lowerText.includes('start') && !lowerText.includes('clonar') && !lowerText.includes('migrar');

if (isVmStatusQuery) {
  try {
    const vmM = text.match(/\b(?:vm_?id|vm|id)?\s*[:=]?\s*(\d+)\b/i);
    let target = vmM ? vmM[1] : '';
    if (!target) {
      let cleaned = text;
      for (const w of ['dime', 'el', 'estado', 'estatus', 'status', 'de', 'la', 'del', 'vm', 'contenedor', 'maquina', 'máquina', 'virtual', 'info', 'ver', 'cómo', 'como', 'está', 'esta']) {
        cleaned = cleaned.replace(new RegExp('\\b' + w + '\\b', 'gi'), ' ');
      }
      target = cleaned.trim();
    }
    if (target) {
      const pmxRes = await this.helpers.httpRequest({
        method: 'POST',
        url: `${ENGINE_BASE}/proxmox/vm-action`,
        body: { target, action: 'status', phase: 'check' },
        json: true,
        timeout: 8000
      });
      if (pmxRes && pmxRes.ok) {
        const emo = pmxRes.estado_actual && pmxRes.estado_actual.includes('RUN') ? '🟢' : '🔴';
        const msg = `🖥️ <b>Información de Máquina Virtual — Proxmox VE</b>\n\n` +
          `• <b>Nombre:</b> ${pmxRes.nombre || 'Desconocido'}\n` +
          `• <b>VMID:</b> <code>${pmxRes.vmid || target}</code>\n` +
          `• <b>Nodo físico:</b> <code>${pmxRes.nodo || 'N/D'}</code>\n` +
          `• <b>Estado:</b> ${emo} <b>${pmxRes.estado_actual || 'UNKNOWN'}</b>\n` +
          `• <b>Uso de CPU:</b> ${pmxRes.cpu || '0%'}\n` +
          `• <b>Memoria RAM:</b> ${pmxRes.memoria || 'N/D'}\n` +
          `• <b>Tiempo activo (Uptime):</b> ${pmxRes.uptime || '0m'}`;
        return [{ json: { action: 'reply', chatId, replyText: msg } }];
      }
    }
  } catch (err) {
    // Si falla el fast path, continúa a la IA (Workflow 2)
  }
}

// 8. Usuario autorizado: Enviar a la IA (Workflow 2)
return [{
  json: {
    action: 'forward',
    chatId,
